@dataclass
class SectorParams:
    min_mem: int = 8          # stocks with data needed for breadth
    min_ret: int = 6          # stocks with a return needed to move the index
    wash_lvl: float = 40.0
    wash_len: int = 30
    t9_hi: float = 80.0
    t9_lo: float = 20.0
    t9_len: int = 5
    t20_hi: float = 70.0
    t20_lo: float = 30.0
    t20_len: int = 10
    cap_lvl: float = 20.0
    conf_lvl: float = 70.0
    win_len: int = 20         # thrust window, and the cool-off between thrust episodes
    fade_p20: float = 30.0
    fade_p50: float = 50.0
    conf_memory: int = 60
    flag_hi: float = 15.0
    flag_lo: float = 10.0
    flag_live: int = 60
    lr_age: int = 15
    lr_carry: int = 30
    hl_min_bars: int = 80
    hl_gap: int = 10
    hl_rise: float = 0.03
    hi_bars: int = 252
    r_len: int = 126
    min_members: int = 10     # industries with fewer universe stocks today are read with their NSE sector


def rolling_min_age(x: np.ndarray, n: int, min_periods: Optional[int] = None) -> np.ndarray:
    """Bars since the lowest value of the last n bars (incl. today); the most recent bar wins ties."""
    mp = n if min_periods is None else min_periods
    out = np.full(len(x), np.nan)
    dq: deque = deque()
    for i, v in enumerate(x):
        while dq and x[dq[-1]] >= v:
            dq.pop()
        dq.append(i)
        while dq[0] <= i - n:
            dq.popleft()
        if i + 1 >= mp:
            out[i] = i - dq[0]
    return out


@dataclass
class _Member:
    act: np.ndarray
    close: np.ndarray
    ret: np.ndarray
    a9: np.ndarray
    a20: np.ndarray
    a50: np.ndarray
    hl: np.ndarray
    hi: np.ndarray
    r126: np.ndarray


def _member(s: pd.Series, cal: pd.DatetimeIndex, p: SectorParams) -> _Member:
    s = pd.to_numeric(s, errors="coerce").dropna()
    s = s[s > 0]                                   # a zero close is a bad print, not a price
    s = s[~s.index.duplicated(keep="last")].sort_index()
    c = s.to_numpy(dtype=float)
    n = len(c)
    nb = np.arange(1, n + 1)
    e9, e20, e50 = P.ema(c, 9), P.ema(c, 20), P.ema(c, 50)
    with np.errstate(invalid="ignore", divide="ignore"):
        a9 = np.where(np.isnan(e9), np.nan, (c > e9).astype(float))
        a20 = np.where(np.isnan(e20), np.nan, (c > e20).astype(float))
        a50 = np.where(np.isnan(e50), np.nan, (c > e50).astype(float))
        pc = np.concatenate([[np.nan], c[:-1]])
        ret = np.where(pc > 0, c / pc - 1.0, np.nan)
    cs = pd.Series(c)
    lo60 = cs.rolling(60, min_periods=60).min().to_numpy()
    off = rolling_min_age(c, 60)
    hl = np.where((nb >= p.hl_min_bars) & ~np.isnan(lo60),
                  ((off >= p.hl_gap) & (c >= lo60 * (1 + p.hl_rise))).astype(float), np.nan)
    hi252 = cs.rolling(p.hi_bars, min_periods=p.hi_bars).max().to_numpy()
    hi = np.where((nb >= p.hi_bars) & ~np.isnan(hi252), (c >= hi252).astype(float), np.nan)
    r126 = np.full(n, np.nan)
    if n > p.r_len:
        r126[p.r_len:] = c[p.r_len:] / c[:-p.r_len] - 1.0
    f = pd.DataFrame({"close": c, "ret": ret, "a9": a9, "a20": a20, "a50": a50, "hl": hl, "hi": hi, "r126": r126},
                     index=s.index).reindex(cal)
    return _Member(act=~f["close"].isna().to_numpy(), close=f["close"].to_numpy(), ret=f["ret"].to_numpy(),
                   a9=f["a9"].to_numpy(), a20=f["a20"].to_numpy(), a50=f["a50"].to_numpy(), hl=f["hl"].to_numpy(),
                   hi=f["hi"].to_numpy(), r126=f["r126"].to_numpy())


def _min_in(x: np.ndarray, i: int, n: int) -> float:
    w = x[max(0, i - n):i + 1]
    w = w[~np.isnan(w)]
    return float(w.min()) if len(w) else np.nan


@dataclass
class GroupResult:
    name: str
    kind: str                     # "industry" or "sector"
    listed: int                   # stocks in the list
    members: List[str]            # stocks with prices
    dates: pd.DatetimeIndex
    p9: np.ndarray
    p20: np.ndarray
    p50: np.ndarray
    ew: np.ndarray
    ew_dd: np.ndarray
    lo_age: np.ndarray
    lr_last: np.ndarray
    state: np.ndarray
    thr_age: np.ndarray
    thr_type: np.ndarray
    ev_c: np.ndarray
    ev_cap: np.ndarray
    ev_fade: np.ndarray
    ev_conf: np.ndarray
    n_act: np.ndarray
    flag_tier: Dict[str, int] = field(default_factory=dict)
    flag_age: Dict[str, Optional[int]] = field(default_factory=dict)
    flag_new: Dict[str, bool] = field(default_factory=dict)
    quartile: Dict[str, int] = field(default_factory=dict)
    rank: Dict[str, int] = field(default_factory=dict)
    ranked: int = 0
    r126: Dict[str, float] = field(default_factory=dict)
    bot_code: Dict[str, int] = field(default_factory=dict)
    close: Dict[str, float] = field(default_factory=dict)
    traded_today: Dict[str, bool] = field(default_factory=dict)


def run_group(name: str, members: List[str], closes: Dict[str, pd.Series], cal: pd.DatetimeIndex,
              p: SectorParams = SectorParams(), kind: str = "industry",
              masks: Optional[Dict[str, np.ndarray]] = None) -> GroupResult:
    """`masks` (optional): per stock, a boolean array over `cal` saying on which days the stock counts (the
    universe rules). Indicators are always computed on the stock's full price history; the mask only decides
    whether that day's reading is counted in the group's breadth, index, higher-low share and leader flags."""
    mem = [m for m in members if m in closes and closes[m] is not None and len(closes[m].dropna()) > 0]
    T, M = len(cal), len(mem)
    S = [_member(closes[m], cal, p) for m in mem]
    act = np.array([s.act for s in S]) if M else np.zeros((0, T), bool)
    if masks is not None and M:
        for k, m in enumerate(mem):
            mk = masks.get(m)
            act[k] &= np.zeros(T, bool) if mk is None else np.asarray(mk, bool)

    def stack(attr):
        return np.array([getattr(s, attr) for s in S]) if M else np.zeros((0, T))

    A9, A20, A50, HL, HI, RET, R126 = (stack(a) for a in ("a9", "a20", "a50", "hl", "hi", "ret", "r126"))
    with np.errstate(invalid="ignore"):
        def pct(A):
            ok = act & ~np.isnan(A)
            n = ok.sum(0)
            k = np.where(ok, A, 0).sum(0)
            return np.where(n >= p.min_mem, 100.0 * k / np.maximum(n, 1), np.nan)

        p9, p20, p50 = pct(A9), pct(A20), pct(A50)
        rok = act & ~np.isnan(RET) & (np.abs(np.nan_to_num(RET, nan=9.0)) < 0.5)
        nret = rok.sum(0)
        sret = np.where(rok, RET, 0).sum(0)
    n_act = act.sum(0)

    ew = np.full(T, np.nan)
    cur = np.nan
    for i in range(T):
        if nret[i] >= p.min_ret:
            cur = 100.0 if np.isnan(cur) else cur * (1 + sret[i] / nret[i])
        ew[i] = cur
    ew_bars = np.cumsum(~np.isnan(ew))
    ew_hi = pd.Series(np.nan_to_num(ew, nan=0.0)).rolling(p.hi_bars, min_periods=1).max().to_numpy()
    with np.errstate(invalid="ignore", divide="ignore"):
        ew_dd = np.where(np.isnan(ew) | (ew_bars < 60), np.nan, ew / ew_hi - 1.0)
    lo_age = np.nan_to_num(rolling_min_age(np.where(np.isnan(ew), 1e12, ew), 60, min_periods=1), nan=9999).astype(int)

    lr_last = np.full(T, np.nan)
    self_hl = np.full((M, T), np.nan)
    last_lr, lr_bar = np.nan, -1
    cur_hl = np.full(M, np.nan)
    for i in range(T):
        lr_now = np.nan
        L = i - int(lo_age[i])
        if ew_bars[i] >= 60 and lo_age[i] <= p.lr_age and M:
            ok = act[:, L] & ~np.isnan(HL[:, L])
            n = int(ok.sum())
            if n >= p.min_mem:
                lr_now = 100.0 * float(HL[ok, L].sum()) / n
        if not np.isnan(lr_now):
            last_lr, lr_bar = lr_now, i
            cur_hl = np.where(act[:, L], HL[:, L], np.nan)
        elif lr_bar >= 0 and i - lr_bar > p.lr_carry:
            last_lr = np.nan
            cur_hl = np.full(M, np.nan)
        lr_last[i] = last_lr
        if M:
            self_hl[:, i] = cur_hl

    state = np.zeros(T, int)
    thr_age = np.full(T, -1)
    thr_type_arr = np.zeros(T, int)
    ev_c, ev_cap, ev_fade, ev_conf = (np.zeros(T, bool) for _ in range(4))
    last_trig = thr_start = conf_bar = fade_bar = None
    thr_type = 0
    for i in range(T):
        has = not np.isnan(p20[i])
        thr9 = (not np.isnan(p9[i])) and p9[i] >= p.t9_hi and np.nan_to_num(_min_in(p9, i, p.t9_len), nan=100) <= p.t9_lo
        thr20 = has and p20[i] >= p.t20_hi and np.nan_to_num(_min_in(p20, i, p.t20_len), nan=100) <= p.t20_lo
        wash = (not np.isnan(p50[i])) and np.nan_to_num(_min_in(p50, i, p.wash_len), nan=100) < p.wash_lvl
        sig_c = thr9 and wash
        sig_cap = (thr9 or thr20) and (not np.isnan(lr_last[i])) and lr_last[i] < p.cap_lvl
        conf = (not np.isnan(p9[i])) and has and (not np.isnan(p50[i])) and p9[i] >= p.conf_lvl and p20[i] >= p.conf_lvl and p50[i] >= p.conf_lvl
        trig = sig_c or sig_cap
        new_ep = trig and (last_trig is None or i - last_trig > p.win_len)
        cap_up = False
        if new_ep:
            thr_start, thr_type = i, (2 if sig_cap else 1)
        elif sig_cap and thr_type == 1 and thr_start is not None and i - thr_start < p.win_len:
            thr_type, cap_up = 2, True
        if trig:
            last_trig = i
        age = None if thr_start is None else i - thr_start
        in_win = age is not None and age < p.win_len
        conf_prev = conf_bar
        if conf:
            conf_bar = i
        fail_t = age is not None and 1 <= age <= p.win_len and has and p20[i] < p.fade_p20 and (not np.isnan(p9[i])) and p9[i] < 50
        post_conf = conf_prev is not None and i - conf_prev <= p.conf_memory and not conf and (not np.isnan(p50[i])) and p50[i] < p.fade_p50
        if fail_t or post_conf:
            fade_bar = i
        fading = (fade_bar is not None and i - fade_bar < p.win_len and (thr_start is None or fade_bar > thr_start)
                  and (conf_bar is None or fade_bar > conf_bar))
        st = 0 if not has else 6 if fading else 4 if (in_win and thr_type == 2) else 3 if in_win else 5 if conf else 2 if wash else 1
        state[i] = st
        thr_age[i] = -1 if age is None else age
        thr_type_arr[i] = thr_type
        ev_c[i] = new_ep and thr_type == 1
        ev_cap[i] = (new_ep and thr_type == 2) or cap_up
        ev_fade[i] = st == 6 and (i == 0 or state[i - 1] != 6)
        ev_conf[i] = conf and (conf_prev is None or i - conf_prev > p.win_len)

    res = GroupResult(name=name, kind=kind, listed=len(members), members=mem, dates=cal, p9=p9, p20=p20, p50=p50,
                      ew=ew, ew_dd=ew_dd, lo_age=lo_age, lr_last=lr_last, state=state, thr_age=thr_age,
                      thr_type=thr_type_arr, ev_c=ev_c, ev_cap=ev_cap, ev_fade=ev_fade, ev_conf=ev_conf, n_act=n_act)
    if T == 0:
        return res
    i = T - 1
    for k, m in enumerate(mem):
        hit = act[k] & (np.nan_to_num(HI[k], nan=0) == 1) & ~np.isnan(ew_dd)
        f1 = np.where(hit & (ew_dd <= -p.flag_lo / 100))[0]
        f2 = np.where(hit & (ew_dd <= -p.flag_hi / 100))[0]
        b1 = int(f1[-1]) if len(f1) else None
        b2 = int(f2[-1]) if len(f2) else None

        def tier_at(j):
            t2 = [b for b in f2 if b <= j]
            t1 = [b for b in f1 if b <= j]
            if t2 and j - t2[-1] <= p.flag_live:
                return 2
            if t1 and j - t1[-1] <= p.flag_live:
                return 1
            return 0

        tier = 2 if (b2 is not None and i - b2 <= p.flag_live) else 1 if (b1 is not None and i - b1 <= p.flag_live) else 0
        res.flag_tier[m] = tier
        res.flag_age[m] = (i - b2) if tier == 2 else (i - b1) if tier == 1 else None
        res.flag_new[m] = tier > (tier_at(i - 1) if i > 0 else 0)
        res.close[m] = float(S[k].close[i]) if act[k, i] else float("nan")
        res.traded_today[m] = bool(act[k, i])
        res.r126[m] = float(R126[k, i]) if act[k, i] else float("nan")
        h, a20 = self_hl[k, i], A20[k, i]
        res.bot_code[m] = 0 if np.isnan(h) else (1 if a20 == 1 else 2) if h == 1 else 3
    ok = [m for k, m in enumerate(mem) if act[k, i] and not np.isnan(R126[k, i])]
    if len(ok) >= p.min_mem:
        vals = sorted(ok, key=lambda m: -res.r126[m])
        n = len(vals)
        res.ranked = n
        for rank, m in enumerate(vals):
            q = rank / n
            res.quartile[m] = 1 if q < 0.25 else 2 if q < 0.5 else 3 if q < 0.75 else 4
            res.rank[m] = rank + 1
    for m in mem:
        res.quartile.setdefault(m, 0)
    return res


