def _num(x, nd=1):
    if x is None:
        return None
    x = float(x)
    return None if (math.isnan(x) or math.isinf(x)) else round(x, nd)


class _Pct:
    """A percentage that prints as "12" (format spec .0f) or "n/a" when missing."""

    def __init__(self, v):
        self.v = v

    def __format__(self, spec):
        return "n/a" if self.v is None else format(self.v, spec)


def _date(d) -> str:
    return pd.Timestamp(d).strftime("%Y-%m-%d")


def study_figures() -> Dict[str, Any]:
    """The study's numbers (data/sector_study.json), for charts and tables on the site."""
    import json
    f = Path(__import__("finlit_technicals").__file__).resolve().parent / "data" / "sector_study.json"
    return json.loads(f.read_text()) if f.exists() else {}


def panel_from_source(source, symbols: List[str]):
    """A Panel (see nse.py) from any price source, for stocks that have prices. Without NSE's files there is no
    series or traded-value data: every traded day counts as EQ and traded value is close x volume."""
    from reference_v201.ref_nse import Panel
    frames = {}
    for s in symbols:
        df = source.daily(s)
        if df is not None and len(df):
            frames[s] = df
    if not frames:
        return None
    dates = pd.DatetimeIndex(sorted(set().union(*[pd.DatetimeIndex(f.index).normalize() for f in frames.values()])))
    keys = sorted(frames)
    T, N = len(dates), len(keys)
    arr = {c: np.full((T, N), np.nan, dtype=np.float64 if c == "close" else np.float32)
           for c in ("open", "high", "low", "close", "volume")}
    for j, k in enumerate(keys):
        f = frames[k]
        f = f[~pd.DatetimeIndex(f.index).normalize().duplicated(keep="last")]
        ti = dates.get_indexer(pd.DatetimeIndex(f.index).normalize())
        for c in arr:
            col = c if c in f else "close"
            arr[c][ti, j] = pd.to_numeric(f[col], errors="coerce").to_numpy() if c != "volume" or "volume" in f else 0
    close = arr["close"]
    close[close <= 0] = np.nan
    vol = np.nan_to_num(arr["volume"].astype(float))
    series = np.where(np.isnan(close), -1, 0).astype(np.int8)
    return Panel(dates=dates, keys=keys, close=close.astype(np.float32), open=arr["open"], high=arr["high"],
                 low=arr["low"], volume=arr["volume"], value=(np.nan_to_num(close) * vol).astype(np.float32),
                 trades=np.where(np.isnan(close), np.nan, 1.0).astype(np.float32), series=series, cum=np.ones((T, N)))


class SectorEngine:
    """Sector breadth for every NSE industry, computed once and answered from the cache.

        nse = NseHistory("~/dhan_alerts/nse_history")    # NSE's daily files (fetch-nse keeps them current)
        eng = SectorEngine(nse)
        eng.board()                      # Sector Pulse: every industry and sector group with a reading
        eng.industry("ferrous-metals")   # one industry page (name or slug)
        eng.stock("SAMBHV")              # the stock inside its industry

    With NseHistory the universe rules (universe.py) decide which stocks count, month by month, including stocks
    later delisted. With any other source (CsvFolder, MemorySource) the same rules run on the stocks that source
    has, using close x volume as traded value and skipping the market-cap rule unless `amfi_dir` is given.
    """

    def __init__(self, source, params: SectorParams = SectorParams(), rules: Optional[UniverseRules] = None,
                 amfi_dir: Optional[str] = None, industries: Optional[Dict[str, tuple]] = None,
                 min_members: Optional[int] = None):
        self.source = source
        self.p = params
        self.min_members = params.min_members if min_members is None else min_members
        folder = getattr(source, "folder", None)
        self.nse = hasattr(source, "panel") and folder is not None
        self.cls = industries if industries is not None else load_industries(
            Path(folder) / "ref" / "industries_extra.json" if folder else None)
        if amfi_dir is None and folder is not None and (Path(folder) / "amfi").exists():
            amfi_dir = str(Path(folder) / "amfi")
        self.amfi_dir = amfi_dir
        self.rules = rules or UniverseRules(use_mcap=amfi_dir is not None)
        if amfi_dir is None:
            self.rules.use_mcap = False
        self._ready = False
        self._res: Dict[str, GroupResult] = {}

    # building
    def _build(self):
        if self._ready:
            return
        if self.nse:
            p = self.source.panel
        else:
            have = self.source.symbols() if hasattr(self.source, "symbols") else list(self.cls)
            norm_have = {norm_symbol(s): s for s in have}
            syms = [norm_have[norm_symbol(s)] for s in self.cls if norm_symbol(s) in norm_have]
            p = panel_from_source(self.source, syms)
            if p is None:
                raise LookupError("no prices for any classified stock in this source")
            # classification by the source's own spelling of the symbol
            self.cls = {**self.cls, **{s: self.cls[next(k for k in self.cls if norm_symbol(k) == norm_symbol(s))]
                                       for s in syms if s not in self.cls}}
        caps, cscale, self.category = None, None, {}
        if self.rules.use_mcap and self.amfi_dir:
            caps, cscale, self.category = amfi_matrix(p, load_amfi(self.amfi_dir))
        self.panel = p
        self.universe = build_universe(p, self.rules, caps, cscale)
        self.classified = np.array([k in self.cls for k in p.keys])
        self.member = self.universe.member & self.classified[None, :]
        self.groups, self.meta = build_groups(p.keys, self.member[-1], self.cls, self.min_members)
        self.col = {k: j for j, k in enumerate(p.keys)}
        self._ready = True

    def calendar(self) -> pd.DatetimeIndex:
        self._build()
        return self.panel.dates

    def board_names(self) -> List[str]:
        """Groups with enough universe members today to read their breadth."""
        self._build()
        return sorted(g for g, cols in self.groups.items() if self.member[-1, cols].sum() >= self.p.min_mem)

    def _find(self, name: str) -> str:
        self._build()
        for g in self.groups:
            if name == g or slug(name) == slug(g) or slug(name) == slug(g + " sector"):
                return g
        for g, m in self.meta.items():                # an industry read inside its sector group
            if any(name == i or slug(name) == slug(i) for i in m["industries"]):
                return g
        raise LookupError(f"{name}: no such NSE industry or sector group")

    def group(self, name: str, kind: Optional[str] = None) -> GroupResult:
        g = self._find(name)
        if g not in self._res:
            p = self.panel
            closes, masks = {}, {}
            for j in self.groups[g]:
                s = pd.Series(p.adj[:, j], index=p.dates).dropna()
                if len(s):
                    closes[p.keys[j]] = s
                    masks[p.keys[j]] = self.member[:, j]
            self._res[g] = run_group(g, list(closes), closes, p.dates, self.p, kind=self.meta[g]["kind"], masks=masks)
            self._res[g].listed = len(self.groups[g])
        return self._res[g]

    def key(self, symbol: str) -> Optional[str]:
        self._build()
        if self.nse:
            return self.source.key(symbol)
        n = norm_symbol(symbol.split(":")[-1])
        return next((k for k in self.panel.keys if norm_symbol(k) == n), None)

    def home(self, symbol: str) -> tuple:
        """(group, kind, key) for a stock: its NSE industry's group."""
        k = self.key(symbol)
        if k is None:
            raise LookupError(f"{symbol}: no NSE prices")
        if k not in self.cls:
            raise LookupError(f"{symbol}: no NSE industry on file (a new listing, an ETF or a fund)")
        j = self.col[k]
        g = next(g for g, cols in self.groups.items() if j in cols)
        return g, self.meta[g]["kind"], k

    def market(self) -> Optional[Dict[str, Any]]:
        """The Nifty 50 against its 200-day average (the market context the study splits results by)."""
        try:
            n = self.source.index("NSE:NIFTY")
        except Exception:      # noqa: BLE001
            n = None
        if n is None or len(n) < 200:
            return None
        c = pd.to_numeric(n["close"], errors="coerce").dropna()
        e = P.ema(c.to_numpy(), 200)
        if np.isnan(e[-1]):
            return None
        above = bool(c.iloc[-1] > e[-1])
        return {"date": _date(c.index[-1]), "nifty50": _num(c.iloc[-1], 2), "nifty50_200d_average": _num(e[-1], 2),
                "pct_vs_200d": _num((c.iloc[-1] / e[-1] - 1) * 100), "above_200d": above,
                "note": MARKET_NOTE[above]}

    # views
    def _row(self, g: GroupResult, i: int = -1) -> Dict[str, Any]:
        n = len(g.dates)
        st = int(g.state[i]) if n else 0
        age = int(g.thr_age[i]) if n and g.thr_age[i] >= 0 else None
        last_thrust = None
        if age is not None:
            j = n + i - age if i < 0 else i - age
            last_thrust = {"type": "CAP" if g.thr_type[i] == 2 else "C", "date": _date(g.dates[j]), "sessions_ago": age}
        lo = int(g.lo_age[i]) if n else None
        flags = [m for m in g.members if g.flag_tier.get(m, 0) > 0]
        meta = self.meta.get(g.name, {"kind": g.kind, "industries": [g.name], "sector": None})
        cols = self.groups.get(g.name, [])
        return {
            "name": g.name, "slug": slug(g.name), "kind": meta["kind"], "sector": meta["sector"],
            "industries": meta["industries"], "date": _date(g.dates[i]) if n else None,
            "state": STATE_NAMES[st], "state_code": STATE_CODES[st], "meaning": STATE_MEANING[st],
            "breadth": {"above_9": _num(g.p9[i]) if n else None, "above_20": _num(g.p20[i]) if n else None,
                        "above_50": _num(g.p50[i]) if n else None,
                        "lowest_50_last_30": _num(_min_in(g.p50, n - 1, self.p.wash_len)) if n else None},
            "index_vs_52w_high": _num(g.ew_dd[i] * 100) if n else None,
            "last_60d_low": None if lo is None or lo >= 9999 else {"sessions_ago": lo, "date": _date(g.dates[n - 1 - lo])},
            "higher_low_share": _num(g.lr_last[i]) if n else None,
            "last_thrust": last_thrust,
            "today": {"thrust_c": bool(g.ev_c[i]), "thrust_cap": bool(g.ev_cap[i]), "turned_fading": bool(g.ev_fade[i]),
                      "confirmed": bool(g.ev_conf[i])} if n else None,
            "leader_flags": len(flags),
            "stocks_counted": int(self.member[-1, cols].sum()) if len(cols) else 0,
            "stocks_listed": int(sum(1 for j in cols if not np.isnan(self.panel.close[-1, j]))),
            "stocks_traded_today": int(g.n_act[i]) if n else 0,
        }

    def summary(self, g: GroupResult) -> str:
        """One plain-English paragraph on the group's state (descriptive only)."""
        r = self._row(g)
        b = {k: (_Pct(v)) for k, v in r["breadth"].items()}
        st, nm = int(g.state[-1]), g.name
        dd = r["index_vs_52w_high"]
        dd_txt = f" The equal-weighted {nm} index is {abs(dd):.1f}% below its 52-week high." if dd is not None and dd < 0 else \
            f" The equal-weighted {nm} index is at its 52-week high." if dd is not None else ""
        t = r["last_thrust"]
        if st == 2:
            return (f"{nm} stocks have been sold broadly. In the last 30 sessions the share above their 50-day average fell "
                    f"as low as {b['lowest_50_last_30']:.0f}%, and today it is {b['above_50']:.0f}%.{dd_txt} "
                    "A thrust (the share above the 9-day average jumping from 20% or less to 80% or more within 5 "
                    "sessions) is what the rules look for next. "
                    + (f"The last thrust, {t['sessions_ago']} sessions ago, did not hold." if t and t["sessions_ago"] <= self.p.wash_len
                       else "None has followed yet."))
        if st in (3, 4):
            when = "today" if t and t["sessions_ago"] == 0 else f"{t['sessions_ago']} sessions ago" if t else ""
            cap = (f" It followed a capitulation: only {r['higher_low_share']:.0f}% of stocks held a higher low at the "
                   "industry's last low.") if st == 4 and r["higher_low_share"] is not None else ""
            left = self.p.win_len - (t["sessions_ago"] if t else 0)
            return (f"{nm} had a broad rebound {when}: after a washout, {b['above_9']:.0f}% of its stocks are above their 9-day "
                    f"average.{cap} The thrust window lasts 20 sessions ({left} left).{dd_txt}")
        if st == 5:
            return (f"{b['above_9']:.0f}%, {b['above_20']:.0f}% and {b['above_50']:.0f}% of {nm} stocks are above their 9, 20 "
                    f"and 50-day averages: most of them are trending up together.{dd_txt}")
        if st == 6:
            return (f"{nm}'s last rebound or uptrend lost its breadth: {b['above_20']:.0f}% of its stocks are above their "
                    f"20-day average and {b['above_50']:.0f}% above their 50-day average.{dd_txt}")
        if st == 1:
            return f"{nm} shows no washout, thrust or broad trend: {b['above_50']:.0f}% of its stocks are above their 50-day average.{dd_txt}"
        return (f"Fewer than {self.p.min_mem} {nm} stocks meet the universe rules today, too few to read breadth.")

    def board(self) -> Dict[str, Any]:
        """Sector Pulse: every group with a reading, the counts by state, the market context and live leader flags."""
        self._build()
        rows, flags, too_few = [], [], []
        names = set(self.board_names())
        for nm in sorted(self.groups):
            if nm not in names:
                too_few.append({"name": nm, "slug": slug(nm), "kind": self.meta[nm]["kind"],
                                "stocks_counted": int(self.member[-1, self.groups[nm]].sum())})
                continue
            g = self.group(nm)
            if not len(g.dates):
                continue
            row = self._row(g)
            if row["state_code"] == "none":
                too_few.append({"name": nm, "slug": slug(nm), "kind": row["kind"], "stocks_counted": row["stocks_counted"]})
                continue
            rows.append(row)
            for m in g.members:
                tier = g.flag_tier.get(m, 0)
                if tier:
                    flags.append({"symbol": m, "group": nm, "group_slug": slug(nm), "tier": "15%+" if tier == 2 else "10-15%",
                                  "tier_code": tier, "sessions_ago": g.flag_age[m], "new_today": bool(g.flag_new.get(m)),
                                  "quarter": g.quartile.get(m) or None, "state": STATE_NAMES[int(g.state[-1])]})
        order = {4: 0, 3: 1, 5: 2, 2: 3, 1: 4, 6: 5, 0: 6}
        code_to_int = {v: k for k, v in STATE_CODES.items()}
        rows.sort(key=lambda r: (order[code_to_int[r["state_code"]]],
                                 r["last_thrust"]["sessions_ago"] if r["state_code"].startswith("thrust") and r["last_thrust"] else 0,
                                 -(r["breadth"]["above_50"] or 0)))
        counts = {STATE_NAMES[k]: 0 for k in (3, 4, 5, 2, 6, 1)}
        for r in rows:
            counts[r["state"]] = counts.get(r["state"], 0) + 1
        flags.sort(key=lambda f: (f["sessions_ago"], -f["tier_code"]))
        n = len(rows)
        fading = counts.get("Fading", 0)
        universe = self.universe_summary()
        universe["counted_in_groups_with_reading"] = sum(r["stocks_counted"] for r in rows)
        return {
            "date": _date(self.panel.dates[-1]),
            "groups": n, "industries": sum(1 for r in rows if r["kind"] == "industry"),
            "stocks_counted": sum(r["stocks_counted"] for r in rows),
            "universe_rules": UNIVERSE_TEXT,
            "counts": counts,
            "state_meanings": {STATE_NAMES[k]: STATE_MEANING[k] for k in (3, 4, 5, 2, 6, 1)},
            "market": self.market(),
            "market_note": (f"{fading} of {n} groups are Fading: breadth is weak across most of the market."
                            if n and fading / n > 0.5 else None),
            "rows": rows,
            "too_few_stocks": too_few,
            "universe": universe,
            "leader_flags": flags,
            "leader_flag_study": FLAG_STUDY,
            "study": {"market": MARKET_STUDY, "rallies": RALLY_STUDY, "limits": STUDY_LIMITS, "figures": study_figures()},
            "disclaimer": DISCLAIMER,
        }

    def universe_summary(self) -> Dict[str, Any]:
        """Market-wide counts for the "which stocks are counted" block: classified stocks with a price on the last day,
        how many meet the rules, how many of those sit in groups with a reading, and why the rest are left out (a stock
        often misses several rules, so the reason counts add up to more than `not_counted`)."""
        self._build()
        listed = members = 0
        reasons: Dict[str, int] = {}
        for cols in self.groups.values():
            for j in cols:
                if np.isnan(self.panel.close[-1, j]):
                    continue
                listed += 1
                if self.member[-1, j]:
                    members += 1
                    continue
                for r in self._stock_reasons(self.panel.keys[j]):
                    reasons[r] = reasons.get(r, 0) + 1
        names = set(self.board_names())
        in_read = sum(int(self.member[-1, cols].sum()) for nm, cols in self.groups.items() if nm in names)
        return {
            "date": _date(self.panel.dates[-1]),
            "stocks_with_industry_traded": listed,
            "meet_rules": members,
            "counted_in_groups_with_reading": in_read,
            "not_counted": listed - members,
            "reasons": [{"reason": r, "stocks": n} for r, n in sorted(reasons.items(), key=lambda x: -x[1])],
        }

    def _stock_reasons(self, key: str) -> list:
        j = self.col[key]
        p = self.panel
        if np.isnan(p.close[-1, j]) and self.universe.inputs["since_trade"][-1, j] >= self.rules.stale_exit:
            traded = np.where(~np.isnan(p.close[:, j]))[0]
            return [f"no trade on NSE since {_date(p.dates[traded[-1]])} (suspended, merged or delisted)"]
        return why_not(self.universe, j)

    def industry(self, name: str, history_sessions: int = 260, peer_labels: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
        """One group's page: state, plain-English summary, breadth history with state bands and events, the study, every
        counted stock ranked by 6-month return, and the group's other listed stocks with the reason they do not count."""
        g = self.group(name)
        if not len(g.dates):
            raise LookupError(f"{name}: no prices")
        row = self._row(g)
        st = int(g.state[-1])
        n = len(g.dates)
        a = max(0, n - history_sessions)
        hist = {"dates": [_date(d) for d in g.dates[a:]], "above_9": [_num(x) for x in g.p9[a:]],
                "above_20": [_num(x) for x in g.p20[a:]], "above_50": [_num(x) for x in g.p50[a:]],
                "state_code": [STATE_CODES[int(x)] for x in g.state[a:]],
                "index_vs_52w_high": [_num(x * 100) if not np.isnan(x) else None for x in g.ew_dd[a:]],
                "stocks_counted": [int(x) for x in g.n_act[a:]]}
        bands, cur, start = [], None, None
        for j in range(a, n):
            s = int(g.state[j])
            if s != cur:
                if cur is not None:
                    bands.append({"state": STATE_NAMES[cur], "state_code": STATE_CODES[cur], "from": _date(g.dates[start]), "to": _date(g.dates[j - 1])})
                cur, start = s, j
        if cur is not None:
            bands.append({"state": STATE_NAMES[cur], "state_code": STATE_CODES[cur], "from": _date(g.dates[start]), "to": _date(g.dates[n - 1])})
        events = [{"date": _date(g.dates[j]), "kind": kind} for j in range(a, n)
                  for arr, kind in ((g.ev_c, "thrust_c"), (g.ev_cap, "thrust_cap"), (g.ev_fade, "turned_fading"), (g.ev_conf, "confirmed"))
                  if arr[j]]
        names = self.source.names() if hasattr(self.source, "names") else {}
        stocks, others = [], []
        counted = [m for m in g.members if self.member[-1, self.col[m]]]
        for m in sorted(counted, key=lambda m: (g.rank.get(m, 10 ** 6), m)):
            tier = g.flag_tier.get(m, 0)
            r126 = g.r126.get(m, float("nan"))
            stocks.append({
                "symbol": m, "name": names.get(m), "industry": self.cls[m][0], "close": _num(g.close.get(m), 2),
                "traded_today": bool(g.traded_today.get(m)), "rank_6m": g.rank.get(m),
                "return_6m_pct": _num(r126 * 100) if not math.isnan(r126) else None,
                "quarter": g.quartile.get(m) or None, "quarter_name": QUARTER_NAMES[g.quartile.get(m, 0)],
                "bottom_code": g.bot_code.get(m, 0), "bottom": BOTTOM_TEXT[g.bot_code.get(m, 0)],
                "bottomed_before": g.bot_code.get(m, 0) in (1, 2), "above_20_day": g.bot_code.get(m, 0) == 1,
                "leader_flag": None if not tier else {"tier": "15%+" if tier == 2 else "10-15%", "tier_code": tier,
                                                      "sessions_ago": g.flag_age[m], "new_today": bool(g.flag_new.get(m))},
                "amfi_category": self.category.get(m), "peer_label": (peer_labels or {}).get(m),
            })
        for j in self.groups[g.name]:
            k = self.panel.keys[j]
            if self.member[-1, j] or np.isnan(self.panel.close[-1, j]):
                continue
            others.append({"symbol": k, "name": names.get(k), "industry": self.cls[k][0],
                           "close": _num(self.panel.adj[-1, j], 2), "not_counted_because": self._stock_reasons(k)})
        dd = row["index_vs_52w_high"]
        flag_note = None
        if dd is not None and dd > -self.p.flag_lo:
            flag_note = (f"No new leader flags are possible today: the {g.name} index is {abs(dd):.1f}% below its high, and a "
                         f"flag needs it 10% or more below (15%+ for the full flag).")
        return {
            **row, "since": bands[-1]["from"] if bands else None, "summary": self.summary(g),
            "rule": STATE_RULE.get(st, ""), "history": hist, "bands": bands, "events": events,
            "study": {"state": STATE_STUDY.get(st, ""), "market": MARKET_STUDY, "rallies": RALLY_STUDY,
                      "leader_flag": FLAG_STUDY, "quarter": QUARTER_STUDY, "bottom": BOTTOM_STUDY, "limits": STUDY_LIMITS},
            "market": self.market(), "ranked_6m": g.ranked, "stocks": stocks, "not_counted": others,
            "universe_rules": UNIVERSE_TEXT, "leader_flag_note": flag_note, "disclaimer": DISCLAIMER,
        }

    def stock(self, symbol: str) -> Dict[str, Any]:
        """The stock inside its industry group: the group's state, and the stock's rank, quarter, bottom timing and
        leader flag, or why it is not counted."""
        nm, kind, key = self.home(symbol)
        g = self.group(nm)
        row = self._row(g)
        names = self.source.names() if hasattr(self.source, "names") else {}
        base = {"symbol": key, "name": names.get(key), "industry": self.cls[key][0], "sector": self.cls[key][1],
                "amfi_category": self.category.get(key),
                "group": {**row, "summary": self.summary(g), "rule": STATE_RULE.get(int(g.state[-1]), ""),
                          "study": STATE_STUDY.get(int(g.state[-1]), "")},
                "market": self.market(), "disclaimer": DISCLAIMER}
        if not self.member[-1, self.col[key]]:
            return {**base, "in_group": False, "not_counted_because": self._stock_reasons(key),
                    "note": (f"{key} is in NSE's {self.cls[key][0]} industry but is not counted in {nm}'s breadth: "
                             + "; ".join(self._stock_reasons(key)) + "."),
                    "universe_rules": UNIVERSE_TEXT}
        tier = g.flag_tier.get(key, 0)
        r126 = g.r126.get(key, float("nan"))
        dd = row["index_vs_52w_high"]
        if tier:
            flag_text = (f"Leader flag ({'15%+' if tier == 2 else '10-15%'} tier), set {g.flag_age[key]} sessions ago: a 52-week "
                         f"closing high while {nm} was well below its own high.")
        elif dd is not None and dd > -self.p.flag_lo:
            flag_text = (f"No leader flag. A flag needs a 52-week closing high while {nm} is 10% or more below its own high "
                         f"(15%+ for the full flag); {nm} is {abs(dd):.1f}% below.")
        else:
            flag_text = f"No leader flag: no 52-week closing high in the last 60 sessions while {nm} was 10%+ below its high."
        return {
            **base, "in_group": True,
            "rank_6m": g.rank.get(key), "ranked_6m": g.ranked,
            "return_6m_pct": _num(r126 * 100) if not math.isnan(r126) else None,
            "quarter": g.quartile.get(key) or None, "quarter_name": QUARTER_NAMES[g.quartile.get(key, 0)],
            "bottom_code": g.bot_code.get(key, 0), "bottom": BOTTOM_TEXT[g.bot_code.get(key, 0)],
            "leader_flag": None if not tier else {"tier": "15%+" if tier == 2 else "10-15%", "tier_code": tier,
                                                  "sessions_ago": g.flag_age[key], "new_today": bool(g.flag_new.get(key))},
            "leader_flag_text": flag_text,
            "study": {"leader_flag": FLAG_STUDY, "quarter": QUARTER_STUDY, "bottom": BOTTOM_STUDY, "limits": STUDY_LIMITS},
        }


def sector_board(source, **kw) -> Dict[str, Any]:
    return SectorEngine(source, **kw).board()


def industry_view(name: str, source, history_sessions: int = 260, **kw) -> Dict[str, Any]:
    return SectorEngine(source, **kw).industry(name, history_sessions=history_sessions)


def stock_sector(symbol: str, source, **kw) -> Dict[str, Any]:
    return SectorEngine(source, **kw).stock(symbol)
